gold_query:
SELECT
?item ?itemLabel ?siteLink
WHERE {
?siteLink schema:about ?item;
schema:isPartOf <https://bn.wikisource.org/>;
wikibase:badge wd:Q20748093.
SERVICE wikibase:label { bd:serviceParam wikibase:language "bn,en".}
}

linked_query:
SELECT ?book ?bookLabel WHERE {
  ?book wdt:P31 wd:Q3331189 .
  ?book wdt:P407 wd:Q9610 .
  ?book wdt:P1957 ?index .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en,bn". }
}

gold_query:
SELECT (COUNT(?thing) AS ?count) ?typeLabel WHERE {
?thing wdt:P1922 [];
wdt:P31 ?type.
SERVICE wikibase:label {bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,de,fr,ru"}
} GROUP BY ?typeLabel
ORDER BY DESC(?count)

linked_query:
SELECT DISTINCT ?item ?itemLabel WHERE {
  ?item wdt:P1922 ?firstLine .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

gold_query:
SELECT ?politicianLabel ?mastodon ?countryLabel
WHERE
{
?politician wdt:P4033 ?mastodon .
?politician wdt:P106 wd:Q82955 . # occupation politician
?politician wdt:P27 ?country .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?countryLabel

linked_query:
SELECT DISTINCT ?politician ?politicianLabel ?mastodon WHERE {
  ?politician wdt:P106 wd:Q82955 .
  ?politician wdt:P4033 ?mastodon .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
}

gold_query:
SELECT ?s ?desc
WHERE
{
?s wdt:P279 wd:Q7725634 .
OPTIONAL {
?s rdfs:label ?desc FILTER (lang(?desc) = "en").
}
}

linked_query:
SELECT ?work ?workLabel ?description WHERE {
  ?work wdt:P31 wd:Q7725634 .
  OPTIONAL {
    ?work schema:description ?description .
    FILTER(LANG(?description) = "en")
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?human ?humanLabel ?weight WHERE {
  ?human wdt:P31 wd:Q5 .
  ?human wdt:P2067 ?weight .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?weight)
LIMIT 20

gold_query:
SELECT
?statue ?statueLabel (SAMPLE(?statueLocation) AS ?statueLocation_) (SAMPLE(?statueImage) AS ?statueImage_)
?person ?personLabel
(IF(?female, "female"@en, "not female"@en) AS ?femaleLabel)
(IF(?hasNobleTitle, "has noble title"@en, "has no noble title"@en) AS ?hasNobleTitleLabel)
(CONCAT(?femaleLabel, ", "@en, ?hasNobleTitleLabel) AS ?layer)
WHERE {
?statue wdt:P31/wdt:P279* wd:Q860861;
wdt:P17 wd:Q145;
wdt:P180|wdt:P547 ?person.
?person wdt:P31 wd:Q5.
BIND(EXISTS { ?person wdt:P21/wdt:P279* wd:Q6581072. } AS ?female)
BIND(EXISTS { ?person wdt:P97 ?nobleTitle. } AS ?hasNobleTitle)
OPTIONAL { ?statue wdt:P625 ?statueLocation. }
OPTIONAL { ?statue wdt:P18 ?statueImage. }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?statue ?statueLabel ?person ?personLabel ?female ?hasNobleTitle

linked_query:
SELECT DISTINCT ?statue ?statueLabel WHERE {
  ?statue wdt:P31 wd:Q179700 .
  ?statue wdt:P17 wd:Q145 .
  ?statue wdt:P180 ?subject .
  {
    ?subject wdt:P21 wd:Q467 .
  } UNION {
    ?subject wdt:P106 wd:Q13417114 .
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?route ?routeLabel WHERE {
  wd:[entity:Antarctic Circumpolar Expedition] wdt:P15 ?route .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

gold_query:
SELECT ?disciplineLabel ?genderLabel (AVG(?height_in_m) AS ?averageheight) (COUNT(?person) AS ?number)
WHERE {
?person wdt:P2416 ?discipline ;
wdt:P641 wd:Q38108 .
?person wdt:P21 ?gender .
?person p:P2048/psn:P2048/wikibase:quantityAmount ?height_in_m .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?disciplineLabel ?genderLabel
ORDER BY ?averageheight

linked_query:
SELECT ?discipline ?disciplineLabel (AVG(?height) AS ?avgHeight) WHERE {
  ?skater wdt:P31 wd:Q5 .
  ?skater wdt:P21 wd:Q6581097 .
  ?skater wdt:P641 wd:Q38108 .
  ?skater wdt:P2048 ?height .
  ?skater wdt:P106 ?discipline .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?discipline ?disciplineLabel

gold_query:
SELECT DISTINCT ?parish ?parishLabel ?coords ?county ?countyLabel WHERE {
?parish wdt:P31/wdt:P279* wd:Q28931907 .
?county wdt:P31/wdt:P279* wd:Q20974973 .
?parish wdt:P131 ?county .
?parish wdt:P625 ?coords.
SERVICE wikibase:label {
bd:serviceParam wikibase:language "en" .
}
}
LIMIT 15000

linked_query:
SELECT ?parish ?parishLabel ?county ?countyLabel ?coord WHERE {
  ?parish wdt:P31 wd:[entity:cadastral division of New South Wales] .
  ?parish wdt:P131 ?county .
  ?county wdt:P31 wd:[entity:Cadastral divisions of New South Wales] .
  OPTIONAL { ?parish wdt:P625 ?coord . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?countyLabel ?parishLabel

